// ============================================================
// Rule: FTG_Conserve Mode Activated
// Vendor: Fortigate
// Objective:
// Detect activity associated with FTG_Conserve Mode Activated.
// Severity: SEV_050_CRITICAL
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1204 - User Execution
// Technique: T1204.002 - User Execution: Malicious File
// Tactic: TA0001 - Initial Access

// Fonte de dados: logs brutos do Fortinet FortiGate
dataset = fortinet_fortigate_raw  

// Filtro para eventos da categoria "system"
// Restrição adicional para mensagens que indiquem "Conserve mode activated"
| filter cat = "system"
       and msg contains "Conserve mode activated"
